(function(){
function safe(fn,name){try{fn();}catch(e){console.warn('init failed:',name,e);}}
// TODO: reemplazar con el numero real de WhatsApp de VIT PAGO (formato: codigo de pais + numero, sin '+' ni espacios)
var WHATSAPP_NUMBER='51900000000';
function buildWaLink(text){
return 'https://wa.me/'+WHATSAPP_NUMBER+'?text='+encodeURIComponent(text||'Hola, quiero mas informacion sobre VIT PAGO.');
}
safe(function navScroll(){
var nav=document.getElementById('nav');
if(!nav)return;
window.addEventListener('scroll',function(){
if(window.scrollY>40){nav.classList.add('scrolled');}
else{nav.classList.remove('scrolled');}
},{passive:true});
},'navScroll');
safe(function revealOnScroll(){
var items=Array.prototype.slice.call(document.querySelectorAll('.reveal'));
if(!items.length)return;
if(!('IntersectionObserver' in window)){
items.forEach(function(el){el.classList.add('in');});
return;
}
var io=new IntersectionObserver(function(entries){
entries.forEach(function(entry){
if(entry.isIntersecting){
entry.target.classList.add('in');
io.unobserve(entry.target);
}
});
},{threshold:0.05,rootMargin:'0px 0px -40px 0px'});
items.forEach(function(el){io.observe(el);});
setTimeout(function(){items.forEach(function(el){el.classList.add('in');});},6000);
},'revealOnScroll');
safe(function mouseGradient(){
var zones=Array.prototype.slice.call(document.querySelectorAll('.hero, .page-hero'));
if(!zones.length)return;
zones.forEach(function(zone){
zone.addEventListener('mousemove',function(e){
var rect=zone.getBoundingClientRect();
var x=((e.clientX-rect.left)/rect.width)*100;
var y=((e.clientY-rect.top)/rect.height)*100;
zone.style.setProperty('--mx',x+'%');
zone.style.setProperty('--my',y+'%');
},{passive:true});
});
},'mouseGradient');
safe(function tiltCards(){
var cards=Array.prototype.slice.call(document.querySelectorAll('.tilt'));
if(!cards.length)return;
cards.forEach(function(card){
card.addEventListener('mousemove',function(e){
var rect=card.getBoundingClientRect();
var px=(e.clientX-rect.left)/rect.width-0.5;
var py=(e.clientY-rect.top)/rect.height-0.5;
var rotateY=px*14;
var rotateX=py*-14;
card.style.transform='perspective(800px) rotateX('+rotateX+'deg) rotateY('+rotateY+'deg) translateY(-4px)';
},{passive:true});
card.addEventListener('mouseleave',function(){
card.style.transform='perspective(800px) rotateX(0) rotateY(0) translateY(0)';
});
});
},'tiltCards');
safe(function heroParallax(){
var hero=document.querySelector('.hero');
var inner=document.querySelector('.hero-inner');
if(!hero||!inner)return;
window.addEventListener('scroll',function(){
var vh=window.innerHeight||800;
var progress=Math.min(Math.max(window.scrollY/vh,0),1);
inner.style.transform='translateY('+(progress*60)+'px)';
inner.style.opacity=String(1-progress*0.8);
},{passive:true});
},'heroParallax');
safe(function wireWhatsappLinks(){
var links=document.querySelectorAll('[data-wa-link]');
links.forEach(function(link){
link.setAttribute('href',buildWaLink(link.getAttribute('data-wa-text')));
link.setAttribute('target','_blank');
link.setAttribute('rel','noopener');
});
},'wireWhatsappLinks');
safe(function contactForm(){
var form=document.getElementById('contact-form');
if(!form)return;
var note=document.getElementById('form-note');
var nombre=form.querySelector('#f-nombre');
var correo=form.querySelector('#f-correo');
var telefono=form.querySelector('#f-telefono');
var mensaje=form.querySelector('#f-mensaje');
var consent=form.querySelector('#f-consent');
function setError(field,message){
var wrapper=field.closest('.field');
var errorEl=wrapper?wrapper.querySelector('.field-error'):null;
if(errorEl)errorEl.textContent=message||'';
if(wrapper)wrapper.classList.toggle('has-error',Boolean(message));
}
function setNote(message,state){
if(!note)return;
note.textContent=message||'';
note.classList.remove('is-error','is-success');
if(state)note.classList.add(state);
}
function validate(){
var valid=true;
if(!nombre.value.trim()){setError(nombre,'Cuéntanos tu nombre.');valid=false;}
else{setError(nombre,'');}
var emailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if(!emailPattern.test(correo.value.trim())){setError(correo,'Ingresa un correo válido.');valid=false;}
else{setError(correo,'');}
var phonePattern=/^[0-9+\s-]{6,15}$/;
if(!phonePattern.test(telefono.value.trim())){setError(telefono,'Ingresa un teléfono válido.');valid=false;}
else{setError(telefono,'');}
if(!consent.checked){setNote('Debes autorizar el uso de tus datos para continuar.','is-error');valid=false;}
else if(note&&note.classList.contains('is-error')){setNote('');}
return valid;
}
[nombre,correo,telefono].forEach(function(el){
el.addEventListener('blur',validate);
});
form.addEventListener('submit',function(e){
e.preventDefault();
if(!validate())return;
var text='Hola, soy '+nombre.value.trim()+'. Mi correo es '+correo.value.trim()+' y mi teléfono '+telefono.value.trim()+'.';
if(mensaje.value.trim())text+=' '+mensaje.value.trim();
window.open(buildWaLink(text),'_blank','noopener');
setNote('Te llevamos a WhatsApp para continuar la conversación.','is-success');
});
},'contactForm');
})();